create or replace function public.signal_start_round(p_room_id uuid,p_spectrum jsonb,p_target integer) returns jsonb language plpgsql security definer set search_path=public,auth as $$ declare r public.rooms; begin if p_target not between 0 and 100 then raise exception 'invalid target';end if;select * into r from public.rooms where id=p_room_id and host_id=auth.uid() for update;if not found then raise exception 'host required';end if;insert into public.rounds(room_id,keeper_id,spectrum,target) values(r.id,auth.uid(),p_spectrum,p_target);update public.rooms set status='clue',game_state=jsonb_build_object('phase','clue') where id=r.id returning * into r;return to_jsonb(r);end;$$;
create or replace function public.signal_submit_clue(p_room_id uuid,p_clue text) returns jsonb language plpgsql security definer set search_path=public,auth as $$ declare r public.rounds; begin select * into r from public.rounds where room_id=p_room_id order by created_at desc limit 1 for update;if not found or r.keeper_id<>auth.uid() then raise exception 'keeper required';end if;if char_length(trim(p_clue)) not between 1 and 60 then raise exception 'invalid clue';end if;update public.rounds set clue=trim(p_clue) where id=r.id;update public.rooms set status='tune',game_state=jsonb_build_object('phase','tune','clue',trim(p_clue)) where id=p_room_id;return jsonb_build_object('ok',true);end;$$;
create or replace function public.signal_submit_tune(p_room_id uuid,p_needle integer) returns jsonb language plpgsql security definer set search_path=public,auth as $$ begin if p_needle not between 0 and 100 or not exists(select 1 from public.room_players p join public.rooms r on r.id=p.room_id where p.room_id=p_room_id and p.user_id=auth.uid() and p.team=r.active_team) then raise exception 'active team required';end if;update public.rounds set needle=p_needle where id=(select id from public.rounds where room_id=p_room_id order by created_at desc limit 1);update public.rooms set status='intercept',game_state=jsonb_build_object('phase','intercept','needle',p_needle) where id=p_room_id;return jsonb_build_object('ok',true);end;$$;
grant execute on function public.signal_start_round(uuid,jsonb,integer),public.signal_submit_clue(uuid,text),public.signal_submit_tune(uuid,integer) to authenticated;
